from collections import defaultdict

file_times = {name: int(time) for name, time in (input().split() for _ in range(int(input())))}
cmds = input().split()

prereqs = defaultdict(set)
actions = defaultdict(list)
default_target, targets, reqs = "", [], []

for _ in range(int(input())):
    line = input().split('#')[0]
    if not line.strip(): continue

    if line.startswith('\t'):
        for t in targets: 
            actions[t].append((line.split(), reqs))
    else:
        tgt_part, req_part = line.split(':', 1)
        targets = list(dict.fromkeys(tgt_part.split()))
        reqs = list(dict.fromkeys(req_part.split()))
        default_target = default_target or targets[0]
        for t in targets: 
            prereqs[t].update(reqs)

vis = {}
def has_cycle(node):
    if node not in vis:
        vis[node] = True
        vis[node] = any(has_cycle(pre) for pre in prereqs[node])
    return vis[node]

if any(has_cycle(node) for node in list(prereqs)):
    print("[Circular dependencies detected]")
else:
    built = {}

    def build(node):
        if node not in built:
            node_time = file_times.get(node, -1)

            outdated = (node not in file_times) | any(
                [build(pre) | (node_time <= file_times.get(pre, -1)) for pre in sorted(prereqs[node])]
            )

            if outdated:
                for tokens, rule_reqs in actions[node]:
                    macros = {'$@': [node], '$<': rule_reqs[:1], '$^': rule_reqs}
                    print(*(tok for t in tokens for tok in macros.get(t, [t])))

            built[node] = outdated
        return built[node]

    for t in (sorted(set(cmds)) if cmds else [default_target]):
        if t: build(t)

    print("[Build complete]")
